package com.example.invoiceadjustment;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import tools.jackson.databind.ObjectMapper; import java.math.BigDecimal; import java.net.URI; import java.time.Instant; import java.util.UUID;
@RestController @RequestMapping("/api/invoice-adjustments") public class InvoiceAdjustmentController {
 private final JdbcClient db; private final ObjectMapper json; public InvoiceAdjustmentController(JdbcClient db,ObjectMapper json){this.db=db;this.json=json;}
 public record Create(@NotNull UUID invoiceId,@NotNull @DecimalMin("0.01") BigDecimal amount,@NotBlank @Pattern(regexp="[A-Z]{3}") String currency,@NotBlank @Size(max=500) String reason){}
 public record Adjustment(UUID id,UUID invoiceId,BigDecimal amount,String currency,String reason,Instant adjustedAt){}
 @PostMapping @Transactional public ResponseEntity<Adjustment> create(@Valid @RequestBody Create r) throws Exception {var v=new Adjustment(UUID.randomUUID(),r.invoiceId(),r.amount(),r.currency(),r.reason(),Instant.now()); db.sql("insert into invoice_adjustments values(:id,:invoice,:amount,:currency,:reason,:at)").param("id",v.id()).param("invoice",v.invoiceId()).param("amount",v.amount()).param("currency",v.currency()).param("reason",v.reason()).param("at",v.adjustedAt()).update(); db.sql("insert into outbox_events values(:id,'invoice',:aggregate,'InvoiceAdjusted',cast(:payload as jsonb),:at)").param("id",UUID.randomUUID()).param("aggregate",v.id()).param("payload",json.writeValueAsString(v)).param("at",v.adjustedAt()).update(); return ResponseEntity.created(URI.create("/api/invoice-adjustments/"+v.id())).body(v);}
}
